--
-- Triggers `tbservis_penawaran_part`
--
DELIMITER $$
CREATE TRIGGER `trg_update_rejection_summary` AFTER UPDATE ON `tbservis_penawaran_part` FOR EACH ROW BEGIN
    IF OLD.status_penawaran='pending'
       AND NEW.status_penawaran IN ('disetujui','ditolak') THEN
        
            noitem, namaitem, total_penawaran, total_diterima, total_ditolak, last_offered_date
        )
        VALUES (
            NEW.kode_barang, NEW.nama_barang, 1,
            IF(NEW.status_penawaran='disetujui',1,0),
            IF(NEW.status_penawaran='ditolak',1,0),
            DATE(NEW.tanggal_penawaran)
        )
        ON DUPLICATE KEY UPDATE
            total_penawaran = total_penawaran + 1,
            total_diterima = total_diterima + IF(NEW.status_penawaran='disetujui',1,0),
            total_ditolak = total_ditolak + IF(NEW.status_penawaran='ditolak',1,0),
            acceptance_rate = (total_diterima / total_penawaran) * 100,
            last_offered_date = DATE(NEW.tanggal_penawaran),
            updated_at = NOW();
    END IF;
END
$$
DELIMITER ;

