DROP TABLE IF EXISTS `master_tarif_jemput`;

CREATE ALGORITHM=UNDEFINED VIEW `master_tarif_jemput`  AS SELECT `master_tarif_jemput_range`.`id` AS `id`, `master_tarif_jemput_range`.`jenis_motor` AS `jenis_motor`, `master_tarif_jemput_range`.`jarak_min` AS `jarak_km`, `master_tarif_jemput_range`.`tarif_dasar` AS `tarif`, `master_tarif_jemput_range`.`keterangan` AS `keterangan`, `master_tarif_jemput_range`.`created_at` AS `created_at`, `master_tarif_jemput_range`.`updated_at` AS `updated_at` FROM `master_tarif_jemput_range` WHERE `master_tarif_jemput_range`.`aktif` = 1 ORDER BY `master_tarif_jemput_range`.`jenis_motor` ASC, `master_tarif_jemput_range`.`jarak_min` ASC ;

