--
-- Structure for view `tblmekanik`
--
DROP TABLE IF EXISTS `tblmekanik`;

CREATE ALGORITHM=MERGE SQL SECURITY INVOKER VIEW `tblmekanik`  AS SELECT `k`.`kode_karyawan` AS `nomekanik`, `k`.`nama_lengkap` AS `nama`, `k`.`alamat` AS `alamat`, `k`.`telp` AS `telp`, CASE WHEN `k`.`kode_posisi` = 'KM' THEN '1' WHEN `k`.`kode_posisi` = 'MK' AND (`k`.`kode_level` in ('MK-1','MS') OR `k`.`kode_level` like 'MK-1%') THEN '2' ELSE '3' END AS `keahlian`, 'aktif' AS `status`, `k`.`email` AS `email`, `k`.`tanggal_masuk` AS `tanggal_masuk`, NULL AS `gaji_pokok`, `k`.`spesialisasi` AS `spesialisasi`, `k`.`sertifikat` AS `sertifikat`, `k`.`created_at` AS `created_at`, `k`.`updated_at` AS `updated_at` FROM `tbuser_karyawan` AS `k` WHERE `k`.`kode_posisi` in ('MK','KM') ;

