CREATE ALGORITHM=MERGE SQL SECURITY INVOKER VIEW `tbl_master_kepala_mekanik`  AS SELECT `k`.`kode_karyawan` AS `id`, coalesce(`k`.`kode_cabang`,'001') AS `kode_cabang`, `k`.`nama_lengkap` AS `nama_kepala_mekanik`, `k`.`kode_karyawan` AS `nip_karyawan`, `k`.`telp` AS `no_telepon`, `k`.`tanggal_masuk` AS `tanggal_mulai`, NULL AS `tanggal_selesai`, 'aktif' AS `status_aktif`, NULL AS `created_by`, `k`.`created_at` AS `created_at`, `k`.`updated_at` AS `updated_at` FROM `tbuser_karyawan` AS `k` WHERE `k`.`kode_posisi` = 'KM' ;

