CREATE ALGORITHM=UNDEFINED VIEW `view_laporan_cancel_servis`  AS SELECT `lc`.`id` AS `id`, `lc`.`no_service` AS `no_service`, `s`.`tanggal` AS `tanggal_service`, `s`.`jam` AS `jam_service`, `lc`.`tanggal_cancel` AS `tanggal_cancel`, `s`.`no_pelanggan` AS `nopelanggan`, `p`.`namapelanggan` AS `namapelanggan`, `s`.`no_polisi` AS `no_polisi`, `lc`.`kategori_alasan` AS `kategori_alasan`, `lc`.`alasan_cancel` AS `alasan_cancel`, `lc`.`biaya_cancel` AS `biaya_cancel`, `lc`.`nominal_dp` AS `nominal_dp`, `lc`.`nominal_refund` AS `nominal_refund`, `lc`.`status_barang` AS `status_barang`, `lc`.`status_pembayaran` AS `status_pembayaran`, `lc`.`user_cancel` AS `user_cancel`, `lc`.`catatan` AS `catatan`, `s`.`kd_cabang` AS `kd_cabang`, to_days(`lc`.`tanggal_cancel`) - to_days(`s`.`created_at`) AS `hari_sejak_input`, CASE WHEN to_days(`lc`.`tanggal_cancel`) - to_days(`s`.`created_at`) <= 1 THEN 'Cepat (1 hari)' WHEN to_days(`lc`.`tanggal_cancel`) - to_days(`s`.`created_at`) <= 3 THEN 'Sedang (2-3 hari)' ELSE 'Lama (>3 hari)' END AS `kategori_waktu_cancel` FROM ((`tb_log_cancel_servis` `lc` left join `tblservice` `s` on(`lc`.`no_service` = `s`.`no_service`)) left join `tblpelanggan` `p` on(`s`.`no_pelanggan` = `p`.`nopelanggan`)) ORDER BY `lc`.`tanggal_cancel` DESC ;

