--
-- Structure for view `view_po_with_pr`
--
DROP TABLE IF EXISTS `view_po_with_pr`;

CREATE ALGORITHM=UNDEFINED VIEW `view_po_with_pr`  AS SELECT `po`.`no_order` AS `no_order`, `po`.`status` AS `status`, `po`.`tanggal` AS `tanggal`, `po`.`tglkirim` AS `tglkirim`, `po`.`no_supplier` AS `no_supplier`, `po`.`note` AS `note`, `po`.`total_qty` AS `total_qty`, `po`.`total_terima` AS `total_terima`, `po`.`total_order` AS `total_order`, `po`.`user` AS `user`, `po`.`Id_tabel` AS `Id_tabel`, `po`.`kd_cabang` AS `kd_cabang`, `po`.`status_pesanan` AS `status_pesanan`, `po`.`tipe_trx` AS `tipe_trx`, `po`.`no_penjualan` AS `no_penjualan`, `po`.`no_pr` AS `no_pr`, `po`.`no_rfq` AS `no_rfq`, `po`.`status_approval` AS `status_approval`, `po`.`approved_by` AS `approved_by`, `po`.`approved_date` AS `approved_date`, `po`.`rejected_by` AS `rejected_by`, `po`.`rejected_date` AS `rejected_date`, `po`.`reject_reason` AS `reject_reason`, `po`.`po_type` AS `po_type`, `po`.`payment_term` AS `payment_term`, `po`.`delivery_address` AS `delivery_address`, `po`.`contact_person` AS `contact_person`, `po`.`contact_phone` AS `contact_phone`, `pr`.`requester` AS `pr_requester`, `pr`.`departemen` AS `pr_departemen`, `pr`.`alasan` AS `pr_alasan` FROM (`tblorder_header` `po` left join `tblpurchase_request_header` `pr` on(`po`.`no_pr` = `pr`.`no_pr`)) ;

-- --------------------------------------------------------

--
-- Structure for view `view_pr_complete`
--
DROP TABLE IF EXISTS `view_pr_complete`;

CREATE ALGORITHM=UNDEFINED VIEW `view_pr_complete`  AS SELECT `h`.`no_pr` AS `no_pr`, `h`.`tanggal_pr` AS `tanggal_pr`, `h`.`tanggal_butuh` AS `tanggal_butuh`, `h`.`requester` AS `requester`, `h`.`departemen` AS `departemen`, `h`.`alasan` AS `alasan`, `h`.`total_qty` AS `total_qty`, `h`.`total_estimasi` AS `total_estimasi`, `h`.`status_pr` AS `status_pr`, `h`.`approved_by` AS `approved_by`, `h`.`approved_date` AS `approved_date`, `h`.`kd_cabang` AS `kd_cabang`, `h`.`created_by` AS `created_by`, `h`.`created_at` AS `created_at`, count(`d`.`id`) AS `jumlah_item`, coalesce(sum(`d`.`quantity`),0) AS `total_qty_detail`, coalesce(sum(`d`.`total_estimasi`),0) AS `total_estimasi_detail`, coalesce(sum(`d`.`qty_po`),0) AS `total_qty_po`, CASE WHEN coalesce(sum(`d`.`quantity`),0) = coalesce(sum(`d`.`qty_po`),0) THEN 'Completed' WHEN coalesce(sum(`d`.`qty_po`),0) > 0 THEN 'Partial' ELSE 'Open' END AS `status_fulfillment` FROM (`tblpurchase_request_header` `h` left join `tblpurchase_request_detail` `d` on(`h`.`no_pr` = `d`.`no_pr`)) GROUP BY `h`.`no_pr` ;

-- --------------------------------------------------------

--
-- Structure for view `view_retur_pembelian`
--
DROP TABLE IF EXISTS `view_retur_pembelian`;

CREATE ALGORITHM=UNDEFINED VIEW `view_retur_pembelian`  AS SELECT `tblretur_pembelian_header`.`noretur` AS `noretur`, `tblretur_pembelian_header`.`nopembelian` AS `nopembelian`, `tblretur_pembelian_header`.`tanggal` AS `tgl_retur`, date_format(`tblretur_pembelian_header`.`tanggal`,'%d/%m/%Y') AS `tanggal_retur`, `tblretur_pembelian_header`.`note` AS `note`, `tblretur_pembelian_header`.`kd_cabang` AS `kd_cabang`, `tblretur_pembelian_header`.`status_retur` AS `status_retur`, `view_pembelian_header`.`tanggal` AS `tgl_beli`, date_format(`view_pembelian_header`.`tanggal`,'%d/%m/%Y') AS `tanggal_beli`, `view_pembelian_header`.`no_order` AS `no_order`, `view_pembelian_header`.`tanggal_order` AS `tgl_order`, date_format(`view_pembelian_header`.`tanggal_order`,'%d/%m/%Y') AS `tanggal_pesan`, `view_pembelian_header`.`no_supplier` AS `no_supplier`, `view_pembelian_header`.`namasupplier` AS `namasupplier` FROM (`tblretur_pembelian_header` join `view_pembelian_header`) WHERE `tblretur_pembelian_header`.`nopembelian` = `view_pembelian_header`.`notransaksi` ;

-- --------------------------------------------------------

--
-- Structure for view `view_ringkasan_kedatangan_pelanggan`
--
DROP TABLE IF EXISTS `view_ringkasan_kedatangan_pelanggan`;

CREATE ALGORITHM=UNDEFINED VIEW `view_ringkasan_kedatangan_pelanggan`  AS SELECT `p`.`nopelanggan` AS `nopelanggan`, `p`.`namapelanggan` AS `namapelanggan`, `p`.`alamat` AS `domisili`, `p`.`telephone` AS `telephone`, `p`.`notlp` AS `notlp`, count(distinct `k`.`id_kedatangan`) AS `jumlah_kedatangan`, count(distinct `k`.`no_service`) AS `jumlah_motor`, sum(`k`.`total_transaksi`) AS `total_nilai_transaksi`, avg(`k`.`total_transaksi`) AS `rata2_nilai_transaksi`, min(`k`.`tanggal_datang`) AS `tanggal_pertama_datang`, max(`k`.`tanggal_datang`) AS `tanggal_terakhir_datang`, max(`k`.`tanggal_datang`) + interval 30 day AS `estimasi_datang_berikutnya`, to_days(curdate()) - to_days(min(`k`.`tanggal_datang`)) AS `lama_pelanggan_hari`, to_days(curdate()) - to_days(max(`k`.`tanggal_datang`)) AS `lama_tidak_datang_hari`, floor((to_days(curdate()) - to_days(min(`k`.`tanggal_datang`))) / 30) AS `tiap_30_hari`, max(`k`.`kedatangan_ke`) AS `total_kunjungan`, avg(`k`.`jarak_hari`) AS `rata2_jarak_kunjungan`, CASE WHEN to_days(curdate()) - to_days(max(`k`.`tanggal_datang`)) > 60 THEN 'Perlu Follow-up Urgent' WHEN to_days(curdate()) - to_days(max(`k`.`tanggal_datang`)) > 30 THEN 'Perlu Follow-up' ELSE 'Aktif' END AS `status_pelanggan`, CASE WHEN count(distinct `k`.`id_kedatangan`) >= 20 THEN '💎 Platinum' WHEN count(distinct `k`.`id_kedatangan`) >= 10 THEN '🥇 Gold' WHEN count(distinct `k`.`id_kedatangan`) >= 5 THEN '🥈 Silver' ELSE '🥉 Bronze' END AS `kategori_member` FROM (`tblpelanggan` `p` left join `master_kedatangan_pelanggan` `k` on(`p`.`nopelanggan` = `k`.`no_pelanggan`)) GROUP BY `p`.`nopelanggan`, `p`.`namapelanggan`, `p`.`alamat`, `p`.`telephone`, `p`.`notlp` ORDER BY max(`k`.`kedatangan_ke`) DESC, sum(`k`.`total_transaksi`) DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_riwayat_kedatangan_detail`
--
DROP TABLE IF EXISTS `view_riwayat_kedatangan_detail`;

CREATE ALGORITHM=UNDEFINED VIEW `view_riwayat_kedatangan_detail`  AS SELECT `k`.`id_kedatangan` AS `id_kedatangan`, `k`.`no_pelanggan` AS `no_pelanggan`, `p`.`namapelanggan` AS `namapelanggan`, `k`.`no_service` AS `no_service`, `k`.`kedatangan_ke` AS `kedatangan_ke`, `k`.`tanggal_datang` AS `tanggal_datang`, `k`.`tanggal_sebelumnya` AS `tanggal_sebelumnya`, `k`.`jarak_hari` AS `jarak_hari`, concat(`k`.`jarak_hari`,' hari') AS `jarak_kunjungan`, `k`.`total_transaksi` AS `total_transaksi`, `k`.`jumlah_item` AS `jumlah_item`, `k`.`rata2_nilai_per_item` AS `rata2_nilai_per_item`, `k`.`estimasi_datang_berikut` AS `estimasi_datang_berikut`, to_days(curdate()) - to_days(`k`.`tanggal_datang`) AS `hari_sejak_servis`, to_days(`k`.`estimasi_datang_berikut`) - to_days(curdate()) AS `hari_sampai_estimasi`, `k`.`status_garansi` AS `status_garansi`, CASE WHEN to_days(curdate()) - to_days(`k`.`tanggal_datang`) <= 30 THEN 'Garansi Aktif' ELSE 'Garansi Expired' END AS `status_garansi_display`, `k`.`keterangan` AS `keterangan`, `k`.`created_at` AS `created_at` FROM (`master_kedatangan_pelanggan` `k` join `tblpelanggan` `p` on(`k`.`no_pelanggan` = `p`.`nopelanggan`)) ORDER BY `k`.`tanggal_datang` DESC, `k`.`kedatangan_ke` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_service`
--
DROP TABLE IF EXISTS `view_service`;

CREATE ALGORITHM=UNDEFINED VIEW `view_service`  AS SELECT `tblservice`.`no_service` AS `no_service`, `tblservice`.`tanggal` AS `tanggal`, date_format(`tblservice`.`tanggal`,'%d/%m/%Y') AS `tanggal_trx`, `tblservice`.`jam` AS `jam`, `tblservice`.`no_pelanggan` AS `no_pelanggan`, `tblservice`.`no_polisi` AS `no_polisi`, `tblservice`.`total_grand` AS `total_grand`, `tblservice`.`kd_cabang` AS `kd_cabang`, `tblpelanggan`.`namapelanggan` AS `namapelanggan`, `tblservice`.`status` AS `status` FROM (`tblservice` join `tblpelanggan`) WHERE `tblservice`.`no_pelanggan` = `tblpelanggan`.`nopelanggan` ;

-- --------------------------------------------------------

--
-- Structure for view `view_servis_keluhan_lengkap`
--
DROP TABLE IF EXISTS `view_servis_keluhan_lengkap`;

CREATE ALGORITHM=UNDEFINED VIEW `view_servis_keluhan_lengkap`  AS SELECT `k`.`id` AS `id`, `k`.`no_service` AS `no_service`, `k`.`keluhan` AS `keluhan`, `k`.`status_pengerjaan` AS `status_pengerjaan`, `k`.`keterangan_tidak_selesai` AS `keterangan_tidak_selesai`, `k`.`auto_workorder` AS `auto_workorder`, `k`.`workorder_applied` AS `workorder_applied`, `k`.`created_at` AS `created_at`, `k`.`updated_at` AS `updated_at`, `s`.`tanggal` AS `tanggal_service`, `s`.`jam` AS `jam_service`, `s`.`no_pelanggan` AS `no_pelanggan`, `s`.`no_polisi` AS `no_polisi`, `s`.`status_servis` AS `status_servis`, `p`.`namapelanggan` AS `namapelanggan`, `p`.`telephone` AS `hp_pelanggan`, `p`.`notlp` AS `hp_pelanggan2`, `p`.`alamat` AS `alamat_pelanggan`, `v`.`kode_merek` AS `kode_merek`, `v`.`tipe` AS `tipe_kendaraan`, `v`.`jenis` AS `jenis_kendaraan`, `v`.`tahun_buat` AS `tahun_buat`, `wo`.`nama_wo` AS `nama_workorder`, (select count(0) from `tbservis_temuan` `t` where `t`.`keluhan_id` = `k`.`id`) AS `jumlah_temuan`, CASE WHEN `k`.`status_pengerjaan` = 'selesai' THEN 'success' WHEN `k`.`status_pengerjaan` = 'diproses' THEN 'warning' WHEN `k`.`status_pengerjaan` = 'tidak_selesai' THEN 'danger' ELSE 'info' END AS `status_badge_color` FROM ((((`tbservis_keluhan_status` `k` left join `tblservice` `s` on(`k`.`no_service` = `s`.`no_service`)) left join `tblpelanggan` `p` on(`s`.`no_pelanggan` = `p`.`nopelanggan`)) left join `tblkendaraan` `v` on(`s`.`no_polisi` = `v`.`nopolisi`)) left join `tbworkorderheader` `wo` on(`k`.`auto_workorder` = `wo`.`kode_wo`)) ORDER BY `k`.`created_at` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_servis_status_summary`
--
DROP TABLE IF EXISTS `view_servis_status_summary`;

CREATE ALGORITHM=UNDEFINED VIEW `view_servis_status_summary`  AS SELECT `s`.`no_service` AS `no_service`, `s`.`tanggal` AS `tanggal`, `s`.`jam` AS `jam`, `s`.`no_pelanggan` AS `no_pelanggan`, `s`.`no_polisi` AS `no_polisi`, `s`.`status_servis` AS `status_servis`, `p`.`namapelanggan` AS `namapelanggan`, `p`.`telephone` AS `hp_pelanggan`, `v`.`kode_merek` AS `kode_merek`, `v`.`tipe` AS `tipe_kendaraan`, `v`.`jenis` AS `jenis_kendaraan`, count(distinct `k`.`id`) AS `total_keluhan`, sum(case when `k`.`status_pengerjaan` = 'selesai' then 1 else 0 end) AS `keluhan_selesai`, sum(case when `k`.`status_pengerjaan` = 'diproses' then 1 else 0 end) AS `keluhan_diproses`, sum(case when `k`.`status_pengerjaan` = 'tidak_selesai' then 1 else 0 end) AS `keluhan_tidak_selesai`, count(distinct `t`.`id`) AS `total_temuan`, sum(case when `t`.`status_temuan` = 'selesai' then 1 else 0 end) AS `temuan_selesai`, sum(case when `t`.`status_temuan` = 'disetujui' then 1 else 0 end) AS `temuan_disetujui`, sum(case when `t`.`status_temuan` = 'ditolak' then 1 else 0 end) AS `temuan_ditolak`, count(distinct `wo`.`id`) AS `total_workorder`, sum(case when `wo`.`status_pengerjaan` = 'selesai' then 1 else 0 end) AS `workorder_selesai`, sum(case when `wo`.`status_pengerjaan` = 'diproses' then 1 else 0 end) AS `workorder_diproses`, sum(case when `wo`.`status_pengerjaan` = 'tidak_selesai' then 1 else 0 end) AS `workorder_tidak_selesai`, CASE WHEN count(distinct `k`.`id`) + count(distinct `wo`.`id`) = 0 THEN 100 ELSE round((sum(case when `k`.`status_pengerjaan` = 'selesai' then 1 else 0 end) + sum(case when `wo`.`status_pengerjaan` = 'selesai' then 1 else 0 end)) * 100.0 / (count(distinct `k`.`id`) + count(distinct `wo`.`id`)),0) END AS `progress_percentage` FROM (((((`tblservice` `s` left join `tblpelanggan` `p` on(`s`.`no_pelanggan` = `p`.`nopelanggan`)) left join `tblkendaraan` `v` on(`s`.`no_polisi` = `v`.`nopolisi`)) left join `tbservis_keluhan_status` `k` on(`s`.`no_service` = `k`.`no_service`)) left join `tbservis_temuan` `t` on(`s`.`no_service` = `t`.`no_service`)) left join `tbservis_workorder` `wo` on(`s`.`no_service` = `wo`.`no_service`)) GROUP BY `s`.`no_service`, `s`.`tanggal`, `s`.`jam`, `s`.`no_pelanggan`, `s`.`no_polisi`, `s`.`status_servis`, `p`.`namapelanggan`, `p`.`telephone`, `v`.`kode_merek`, `v`.`tipe`, `v`.`jenis` ORDER BY `s`.`tanggal` DESC, `s`.`jam` DESC ;

-- --------------------------------------------------------

--
-- Structure for view `view_servis_temuan_lengkap`
--
DROP TABLE IF EXISTS `view_servis_temuan_lengkap`;

CREATE ALGORITHM=UNDEFINED VIEW `view_servis_temuan_lengkap`  AS SELECT `t`.`id` AS `id`, `t`.`no_service` AS `no_service`, `t`.`keluhan_id` AS `keluhan_id`, `t`.`kode_temuan` AS `kode_temuan`, `t`.`temuan_custom` AS `temuan_custom`, `t`.`deskripsi_temuan` AS `deskripsi_temuan`, `t`.`jenis_perbaikan` AS `jenis_perbaikan`, `t`.`status_temuan` AS `status_pengerjaan`, `t`.`keterangan_tidak_selesai` AS `keterangan_tidak_selesai`, `t`.`tingkat_urgensi` AS `tingkat_urgensi`, `t`.`estimasi_biaya` AS `estimasi_biaya`, `t`.`created_at` AS `created_at`, `t`.`updated_at` AS `updated_at`, `k`.`keluhan` AS `keluhan`, `k`.`status_pengerjaan` AS `status_keluhan`, `mt`.`nama_temuan` AS `nama_temuan`, `mt`.`kategori` AS `kategori_temuan`, `s`.`tanggal` AS `tanggal_service`, `s`.`jam` AS `jam_service`, `s`.`no_pelanggan` AS `no_pelanggan`, `s`.`no_polisi` AS `no_polisi`, `p`.`namapelanggan` AS `namapelanggan`, `p`.`telephone` AS `hp_pelanggan`, `p`.`notlp` AS `hp_pelanggan2`, `v`.`kode_merek` AS `kode_merek`, `v`.`tipe` AS `tipe_kendaraan`, `v`.`jenis` AS `jenis_kendaraan`, (select count(0) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id`) AS `jumlah_penawaran`, (select count(0) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id` and `pp`.`status_penawaran` = 'pending') AS `penawaran_pending`, coalesce(`t`.`temuan_custom`,`mt`.`nama_temuan`) AS `nama_temuan_display`, CASE WHEN `t`.`status_temuan` = 'selesai' THEN 'success' WHEN `t`.`status_temuan` = 'disetujui' THEN 'primary' WHEN `t`.`status_temuan` = 'ditawarkan' THEN 'warning' WHEN `t`.`status_temuan` = 'ditolak' THEN 'danger' WHEN `t`.`status_temuan` = 'ditemukan' THEN 'info' ELSE 'default' END AS `status_badge_color`, CASE WHEN `t`.`tingkat_urgensi` = 'urgent' THEN 'danger' WHEN `t`.`tingkat_urgensi` = 'tinggi' THEN 'warning' WHEN `t`.`tingkat_urgensi` = 'sedang' THEN 'info' WHEN `t`.`tingkat_urgensi` = 'rendah' THEN 'default' ELSE 'default' END AS `urgency_badge_color` FROM (((((`tbservis_temuan` `t` left join `tbservis_keluhan_status` `k` on(`t`.`keluhan_id` = `k`.`id`)) left join `tbmaster_temuan` `mt` on(`t`.`kode_temuan` = `mt`.`kode_temuan`)) left join `tblservice` `s` on(`t`.`no_service` = `s`.`no_service`)) left join `tblpelanggan` `p` on(`s`.`no_pelanggan` = `p`.`nopelanggan`)) left join `tblkendaraan` `v` on(`s`.`no_polisi` = `v`.`nopolisi`)) ORDER BY `t`.`created_at` DESC ;

