CREATE ALGORITHM=UNDEFINED VIEW `view_stok`  AS SELECT `tbstok`.`tipe` AS `tipe`, `tbstok`.`no_transaksi` AS `no_transaksi`, `tbstok`.`no_item` AS `no_item`, `tbstok`.`tanggal` AS `tanggal`, `tbstok`.`masuk` AS `masuk`, `tbstok`.`keluar` AS `keluar`, `tbstok`.`keterangan` AS `keterangan`, `tbstok`.`id` AS `id`, date_format(`tbstok`.`tanggal`,'%d/%m/%Y') AS `tgl_trx`, `tblitem`.`namaitem` AS `namaitem`, `tbstok`.`kd_cabang` AS `kd_cabang` FROM (`tbstok` join `tblitem`) WHERE `tbstok`.`no_item` = `tblitem`.`noitem` ;

