--
-- Structure for view `view_suggested_parts`
--
DROP TABLE IF EXISTS `view_suggested_parts`;

CREATE ALGORITHM=UNDEFINED VIEW `view_suggested_parts`  AS SELECT `m`.`kode_temuan` AS `kode_temuan`, `mt`.`nama_temuan` AS `nama_temuan`, `m`.`noitem` AS `kode_barang`, `i`.`namaitem` AS `nama_barang`, `i`.`hargajual` AS `harga_jual`, `i`.`quantity` AS `stok`, `i`.`jenis` AS `kategori`, `m`.`is_primary` AS `is_primary`, `m`.`prioritas` AS `prioritas`, `m`.`qty_default` AS `qty_default`, `m`.`keterangan` AS `keterangan`, CASE WHEN `i`.`quantity` > 5 THEN 'ready_stock' WHEN `i`.`quantity` > 0 THEN 'stok_terbatas' ELSE 'indent' END AS `status_stok` FROM ((`tbmaster_temuan_barang_mapping` `m` join `tbmaster_temuan` `mt` on(`m`.`kode_temuan` collate utf8mb4_unicode_ci = `mt`.`kode_temuan` collate utf8mb4_unicode_ci)) join `tblitem` `i` on(`m`.`noitem` collate utf8mb4_unicode_ci = `i`.`noitem` collate utf8mb4_unicode_ci)) WHERE `m`.`status_aktif` = 1 AND `i`.`statusitem` ORDER BY `m`.`kode_temuan` ASC, `m`.`is_primary` DESC, `m`.`prioritas` ASC ;

