DROP TABLE IF EXISTS `view_temuan_penawaran_summary`;

CREATE ALGORITHM=UNDEFINED VIEW `view_temuan_penawaran_summary`  AS SELECT `t`.`id` AS `temuan_id`, `t`.`no_service` AS `no_service`, `s`.`tanggal` AS `tanggal_service`, `s`.`no_polisi` AS `no_polisi`, `k`.`keluhan` AS `keluhan`, coalesce(`mt`.`nama_temuan`,`t`.`temuan_custom`) AS `nama_temuan`, `t`.`deskripsi_temuan` AS `deskripsi_temuan`, `t`.`jenis_perbaikan` AS `jenis_perbaikan`, `t`.`status_temuan` AS `status_temuan`, `t`.`tingkat_urgensi` AS `tingkat_urgensi`, `t`.`estimasi_biaya` AS `estimasi_biaya`, `t`.`biaya_actual` AS `biaya_actual`, `t`.`mekanik_name` AS `mekanik_name`, (select count(0) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id`) AS `total_part_ditawarkan`, (select count(0) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id` and `pp`.`status_penawaran` = 'disetujui') AS `total_part_disetujui`, (select count(0) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id` and `pp`.`status_penawaran` = 'ditolak') AS `total_part_ditolak`, (select sum(`pp`.`total_harga`) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id`) AS `total_nilai_penawaran`, (select sum(`pp`.`total_harga`) from `tbservis_penawaran_part` `pp` where `pp`.`temuan_id` = `t`.`id` and `pp`.`status_penawaran` = 'disetujui') AS `total_nilai_disetujui`, `t`.`created_at` AS `created_at`, `t`.`updated_at` AS `updated_at` FROM (((`tbservis_temuan` `t` left join `tblservice` `s` on(`t`.`no_service` = `s`.`no_service`)) left join `tbservis_keluhan_status` `k` on(`t`.`keluhan_id` = `k`.`id`)) left join `tbmaster_temuan` `mt` on(`t`.`kode_temuan` = `mt`.`kode_temuan`)) ORDER BY `t`.`created_at` DESC ;

