DROP TABLE IF EXISTS `view_user_details`;

CREATE ALGORITHM=UNDEFINED  SQL SECURITY DEFINER VIEW `view_user_details`  AS SELECT `u`.`id` AS `id`, `u`.`nama_user` AS `nama_user`, `u`.`user_akses` AS `user_akses`, `u`.`role_name` AS `role_name`, `u`.`department` AS `department`, `u`.`is_active` AS `is_active`, `u`.`last_login` AS `last_login`, `ur`.`role_description` AS `role_description`, `ur`.`permissions` AS `permissions`, CASE WHEN `u`.`user_akses` in (4,10) THEN 'Workshop' WHEN `u`.`user_akses` in (1,7) THEN 'Management' WHEN `u`.`user_akses` in (2,6) THEN 'Front Office' WHEN `u`.`user_akses` = 8 THEN 'Finance' ELSE 'Other' END AS `role_category` FROM (`tbuser` `u` left join `tb_user_roles` `ur` on(`u`.`user_akses` = `ur`.`role_code`)) ;

