--
-- Structure for view `v_do_status`
--
DROP TABLE IF EXISTS `v_do_status`;

CREATE VIEW `v_do_status` AS 
SELECT 
    `h`.`no_do` AS `no_do`, 
    `h`.`no_po` AS `no_po`, 
    `h`.`no_supplier` AS `no_supplier`, 
    `h`.`tanggal_do` AS `tanggal_do`, 
    `h`.`tanggal_kirim` AS `tanggal_kirim`, 
    `h`.`tanggal_estimasi_tiba` AS `tanggal_estimasi_tiba`, 
    `h`.`status_do` AS `status_do`, 
    `h`.`kd_cabang` AS `kd_cabang`, 
    `h`.`created_by` AS `user`, 
    count(distinct `d`.`no_item`) AS `total_items`, 
    sum(`d`.`qty_kirim`) AS `total_qty_kirim`, 
    sum(`d`.`qty_terima`) AS `total_qty_terima`, 
    sum(`d`.`qty_reject`) AS `total_qty_reject`, 
    CASE WHEN sum(`d`.`qty_kirim`) = 0 THEN 0 ELSE round(sum(`d`.`qty_terima`) / sum(`d`.`qty_kirim`) * 100,2) END AS `persen_terima` 
FROM (`tbldelivery_order_header` `h` 
LEFT JOIN `tbldelivery_order_detail` `d` ON `h`.`no_do` = `d`.`no_do`) 
GROUP BY `h`.`no_do`, `h`.`no_po`, `h`.`no_supplier`, `h`.`tanggal_do`, `h`.`status_do`, `h`.`kd_cabang`, `h`.`created_by`;

-- --------------------------------------------------------

--
-- Structure for view `v_po_status`
