DROP TABLE IF EXISTS `v_po_status`;

CREATE ALGORITHM=UNDEFINED VIEW `v_po_status`  AS SELECT `h`.`no_order` AS `no_order`, `h`.`no_pr` AS `no_pr`, `h`.`no_supplier` AS `no_supplier`, `h`.`tanggal` AS `tanggal`, `h`.`kd_cabang` AS `kd_cabang`, `h`.`status` AS `status`, `h`.`status_approval` AS `status_approval`, `h`.`approved_by` AS `approved_by`, `h`.`approved_date` AS `approved_date`, count(distinct `d`.`no_item`) AS `total_items`, sum(`d`.`quantity`) AS `total_qty_po`, sum(`d`.`qty_terima`) AS `total_qty_terima`, CASE WHEN sum(`d`.`quantity`) = 0 THEN 0 ELSE round(sum(`d`.`qty_terima`) / sum(`d`.`quantity`) * 100,2) END AS `persen_terima` FROM (`tblorder_header` `h` left join `tblorder_detail` `d` on(`h`.`no_order` = `d`.`no_order`)) GROUP BY `h`.`no_order`, `h`.`no_pr`, `h`.`no_supplier`, `h`.`tanggal`, `h`.`kd_cabang`, `h`.`status`, `h`.`status_approval`, `h`.`approved_by`, `h`.`approved_date` ;

-- --------------------------------------------------------

